  {t="A", seg=1, q={4641}, names={"Your Place In The World"}, text="Kaltunk stands right in front of you when you log in. Got a Valley of Trials Gift Voucher in your bags? Hand it to Magga beside the Den for a small gift (no XP)", zone="Durotar", map=1411, x=43.3, y=68.6},
