  {t="C", seg=1, q={5441,4402,789}, names={"Lazy Peons","Galgar's Cactus Apple Surprise","Sting of the Scorpid"}, text="Work your way north: Lazy Peons nap under the trees along the valley sides (use the Blackjack on them only while they are asleep), Cactus Apples sit at the foot of the cactuses, and Scorpid Workers crawl everywhere. Any tails still missing can be finished on the walk back", zone="Durotar", map=1411, x=44.4, y=60.5},
