  {t="C", seg=2, q={96821}, names={"Legging It"}, text="Ridgeshade Creepers and Lurkers (spiders) live along the road north to Razor Hill (50-53, 48-65). Kill 6 of each as you walk. The Echo Isles quests come later", zone="Durotar", map=1411, x=51.5, y=58.3, path={{53.2,73.2},{53.2,69.3},{54.8,63.3}}},
