  {t="C", seg=2, q={96822}, names={"For Honor"}, text="Tiragarde Keep, south-east of Razor Hill: the Raider's Battleaxe, Bow and Shield lie on the ground among the ruined huts and walls around the keep. Search the outskirts before going inside", zone="Durotar", map=1411, x=57.5, y=54.5},
  {t="C", seg=2, q={784,784,791}, obj={1,2,0}, names={"Vanquish the Betrayers","Vanquish the Betrayers","Carry Your Weight"}, text="Kill 10 Kul Tiras Sailors and 8 Marines in and around the keep; they drop the 8 Canvas Scraps. They stand in twos and threes: pull with Lightning Bolt to a doorway, drop Earthbind Totem if one runs, and Healing Wave between pulls", zone="Durotar", map=1411, x=58.5, y=56.5},
