  {t="A", seg=2, q={830}, names={"The Admiral's Orders"}, text="Open Benedict's Chest on the same top floor with the key. The Aged Envelope inside starts The Admiral's Orders", zone="Durotar", map=1411, x=59.3, y=57.6},
