  {t="C", seg=2, q={837,837}, obj={1,2}, names={"Encroachment","Encroachment"}, text="West of Razor Hill: kill 4 Razormane Quilboars and 4 Razormane Scouts on the plain just south-west of town", zone="Durotar", map=1411, x=47.5, y=48.8},
  {t="C", seg=2, q={96825,837}, names={"This Fruit Could Bite Back","Encroachment"}, text="Razormane Grounds, the quilboar camps in the hills to the north-west: kill 4 Dustrunners (8-9) and 4 Battleguards (9-10) and pick 8 Prickly Pear Fruit from the cactuses there. Battleguards hit hard: Stoneclaw Totem if two come, Healing Wave between pulls. Still level 8 when you are done? Kill a few more quilboars: Orgnil's next quest needs level 9", zone="Durotar", map=1411, x=43.0, y=39.0},
