  {t="A", seg=4, q={97253}, names={"Parts and Pieces"}, text="Wrenix the Wretched", zone="The Barrens", map=1413, x=63.1, y=36.4},
  {t="C", seg=4, q={887,895,97253}, names={"Southsea Freebooters","WANTED: Baron Longshore","Parts and Pieces"}, text="Pirate camp on the coast south of Ratchet: kill Southsea Brigands and Cannoneers, kill Baron Longshore (16) for his head, and pick up 5 Handfuls of Complicated Parts on the higher ground at the west side of the camp. Clear the pirates around the Baron before you pull him; Stoneclaw Totem soaks an extra pirate", zone="The Barrens", map=1413, x=63.3, y=46.0},
  {t="T", seg=4, q={887}, names={"Southsea Freebooters"}, zone="The Barrens", map=1413, x=62.7, y=36.3},
