  {t="T", seg=4, q={890}, names={"The Missing Shipment"}, text="Dizzywig on the dock", zone="The Barrens", map=1413, x=63.3, y=38.4},
  {t="A", seg=4, q={892}, names={"The Missing Shipment"}, zone="The Barrens", map=1413, x=63.3, y=38.4},
