  {t="C", seg=5, q={6461}, obj={1}, names={"Blood Feeders"}, text="Kill Deepmoss Creepers along the road north-west of Malaka'jin (around 61-68, 81-93, then 58-61, 72-79) on your way north. Do not go west into Sishir Canyon (about 52-56, 71-76): it is the lair of Besseleth, a level 21 elite spider. You pass her wanted poster on the road (59.1, 75.7): skip Arachnophobia, it is elite", zone="Stonetalon Mountains", map=1442, x=64.5, y=85.0},
  {t="T", seg=5, q={1483}, names={"Ziz Fizziks"}, text="Ziz Fizziks, the gnome on the south-west edge of Windshear Crag", zone="Stonetalon Mountains", map=1442, x=59, y=62.6},
