  {t="C", seg=5, q={6461}, obj={2}, names={"Blood Feeders"}, text="Only if you still need Deepmoss Venomspitters: more roam the slopes just east of Sun Rock (52-54, 54-62), on your way west. Finish them here: on the way south to the cave the only other Venomspitters are in Besseleth's canyon", zone="Stonetalon Mountains", map=1442, x=52.6, y=58.5},
  {t="F", seg=5, arg="Sun Rock Retreat", text="Tharm, the wind rider master on the west side of Sun Rock Retreat", zone="Stonetalon Mountains", map=1442, x=45.1, y=59.8},
