  {t="C", seg=5, q={6421}, names={"Boulderslide Ravine"}, text="Follow the road south from Sun Rock, past the wanted poster, to the Boulderslide Ravine cave: kobolds drop Resonite Crystals and more crystals lie on the cave floor. Go all the way to the back of the cave for the investigation credit. Creepers along the road count for Blood Feeders, but do not cut through Sishir Canyon (about 53, 73): Besseleth (21, elite) lives there", zone="Stonetalon Mountains", map=1442, x=58.5, y=89.5, path={{49.6,61.8},{51.8,61.8},{52.8,63.6},{52.6,70.5},{54.0,74.4},{57.4,77.4},{62.0,77.7},{62.4,85.2},{63.8,87.3},{63.8,90.9},{61.5,91.8}}, cave=true},
