  {t="T", seg=5, q={853}, names={"Apothecary Zamah"}, text="Apothecary Zamah, in the Pools of Vision: the cave under Spirit Rise, reached by a path on Spirit Rise", zone="Thunder Bluff", map=1456, x=23.1, y=21.2},
