  {t="FLY", seg=6, arg="Orgrimmar", text="Run back north to Camp Taurajo (Ghost Wolf) and fly from there"},
  {t="T", seg=6, q={3923}, names={"Rilli Greasygob"}, text="Rilli Greasygob in the Valley of Honor (76.5, 24.4). Skip her follow-up, Samophlange Manual.", zone="Orgrimmar", map=1454, x=76.5, y=24.4},
  {t="N", seg=6, arg="Leave Orgrimmar by the main gate and take the zeppelin to the Undercity", text="Frezza's platform, on the tower just outside the gate. Do not board the Grom'gol zeppelin on the other platform. It lands at the tower in Tirisfal Glades.", zone="Durotar", map=1411, x=50.8, y=13.5},
  {t="F", seg=6, arg="Undercity", text="From the Tirisfal tower walk south into the Ruins of Lordaeron and take the elevator down into the Undercity. Michael Garrett, the bat handler, stands by the west elevator. You need this flight path so that flights from Tarren Mill can reach the Sepulcher.", zone="Undercity", map=1458, x=63.3, y=48.6},
  {t="T", seg=6, q={5725}, names={"The Power to Destroy..."}, zone="Undercity", map=1458, x=56.3, y=92.2, dg=1},
  {t="A", seg=6, q={92421}, names={"Light's Justice"}, text="Morbin Lightbane in the Royal Quarter. Collect 25 Intact Limbs in the Ruins of Lordaeron.", zone="Undercity", map=1458, x=57.8, y=89.8, dg=2},
  {t="A", seg=6, q={95216}, names={"The New Plague"}, text="Theodore Griffs in the Apothecarium. The Highly Toxic Strain drops from Witherfang.", zone="Undercity", map=1458, x=46.6, y=71.4, dg=2},
  {t="N", seg=6, arg="Optional dungeon: Ruins of Lordaeron, levels 15-20", text="The entrance is in the ruined city above the Undercity. Inside: The Baron drops an Abominable Head that starts Unending Torment, and a Crest of Lordaeron lies in a tower near Bjork or on the wall of the small temple at the far end (it moves) and starts a quest too. Quests you picked up for it: Light's Justice, The New Plague. Not on your path, only if you want the detour: The Wrath of Rath'mael (Tirisfal Glades 65, 60); A Frightened Request (Silverpine Forest 44, 43).", zone="Undercity", map=1458, x=72.4, y=11.4, dg=2, run=true},
  {t="T", seg=6, q={92421}, names={"Light's Justice"}, zone="Undercity", map=1458, x=57.8, y=89.8, dg=2},
  {t="T", seg=6, q={95216}, names={"The New Plague"}, zone="Undercity", map=1458, x=46.6, y=71.4, dg=2},
  {t="T", seg=6, q={97288}, names={"Unending Torment"}, text="Bring the Abominable Head to Master Apothecary Faranell.", zone="Undercity", map=1458, x=48.6, y=68.8, dg=2},
  {t="A", seg=6, q={97289}, names={"Unending Torment"}, zone="Undercity", map=1458, x=48.6, y=68.8, dg=2, req=97288},
  {t="T", seg=6, q={97289}, names={"Unending Torment"}, text="Put the head next to the Unfinished Abomination in the next room.", zone="Undercity", map=1458, x=45.9, y=61.8, dg=2, req=97289},
  {t="A", seg=6, q={97290}, names={"Unending Torment"}, zone="Undercity", map=1458, x=45.9, y=61.8, dg=2, req=97289},
  {t="T", seg=6, q={97290}, names={"Unending Torment"}, zone="Undercity", map=1458, x=48.6, y=68.8, dg=2, req=97290},
  {t="A", seg=6, q={97291}, names={"Unending Torment"}, zone="Undercity", map=1458, x=48.6, y=68.8, dg=2, req=97290},
  {t="T", seg=6, q={97291}, names={"Unending Torment"}, text="Get a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed by the herbalism trainer and Essence of Agony from the poison vendor in the Rogues' Quarter, then return to Faranell.", zone="Undercity", map=1458, x=48.6, y=68.8, dg=2, req=97291},
  {t="A", seg=6, q={97292}, names={"Unending Torment"}, zone="Undercity", map=1458, x=48.6, y=68.8, dg=2, req=97291},
  {t="T", seg=6, q={97292}, names={"Unending Torment"}, text="Use the Hissing Serum on the pipes above the abomination, then return to Faranell.", zone="Undercity", map=1458, x=48.6, y=68.8, dg=2, req=97292},
  {t="T", seg=6, q={95204}, names={"Crest of Lordaeron"}, text="Crest of Lordaeron: Oran Snakewrithe.", zone="Undercity", map=1458, x=73.2, y=32.8, dg=2},
  {t="A", seg=6, q={1013}, names={"The Book of Ur"}, text="Keeper Bel'dugur in the Apothecarium. The Book of Ur is on a bookshelf near the end of the keep.", zone="Undercity", map=1458, x=53.7, y=54.5, dg=4},
  {t="N", seg=6, arg="Walk to the Sepulcher", text="Go back up to the ruins and take the road west into Silverpine Forest (it enters the zone in its north-east corner). Follow it south (Ghost Wolf) to the Sepulcher, the crypt hill west of the road about halfway down the zone."},
  {t="F", seg=6, arg="The Sepulcher", text="Karos Razok, the bat handler just east of the crypts", zone="Silverpine Forest", map=1421, x=45.6, y=42.6},
  {t="T", seg=6, q={3301}, names={"Mura Runetotem"}, text="Mura Runetotem, beside the inn", zone="Silverpine Forest", map=1421, x=43, y=42},
  {t="T", seg=6, q={264}, names={"Until Death Do Us Part"}, text="Click Yuriv's Tombstone in the Sepulcher graveyard to place Clarice's Pendant", zone="Silverpine Forest", map=1421, x=44.2, y=42.7},
  {t="T", seg=6, q={92401}, names={"A Frightened Request"}, zone="Silverpine Forest", map=1421, x=44.4, y=43.0, dg=2},
  {t="A", seg=6, q={98299}, names={"Stop the Spread"}, text="Dalar Dawnweaver (new in Forever)", zone="Silverpine Forest", map=1421, x=44.2, y=39.9},
  {t="A", seg=6, q={516}, names={"Beren's Peril"}, text="Shadow Priest Allister. Ignore his low-level Border Crossings, and skip the Shadowfang Keep quests in the Sepulcher (dungeon).", zone="Silverpine Forest", map=1421, x=44.0, y=40.9},
  {t="A", seg=6, q={95981}, names={"Watching the Roads"}, text="Shadow Priest Allister: Watching the Roads (new). It follows his Dalaran pendant chain, which you have not done, so he may not offer it. If he does not, press Skip here and on its two later steps.", zone="Silverpine Forest", map=1421, x=44.1, y=41.0},
  {t="A", seg=6, q={493}, names={"Journey to Hillsbrad Foothills"}, text="Apothecary Renferrel", zone="Silverpine Forest", map=1421, x=42.8, y=40.9},
  {t="C", seg=6, q={98299}, names={"Stop the Spread"}, text="Run south on the road past Pyrewood to the Greymane Wall. Kill 5 Sickly and 5 Haggard Refugees (18-20) in the camp below the wall.", zone="Silverpine Forest", map=1421, x=46.0, y=84.3},
  {t="C", seg=6, q={516}, names={"Beren's Peril"}, text="Follow the road east to Beren's Peril, the cave just north of the road (around 59, 72). Kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians (19-21) and work your way to the back. Pull one at a time; if two come, drop Stoneclaw Totem, and Healing Wave between pulls.", zone="Silverpine Forest", map=1421, x=58.7, y=71.2, path={{60.2,72.0}}, cave=true},
  {t="A", seg=6, q={95884}, names={"The Offering Stone"}, text="A Note Scrap drops from the undead in the cave. Right-click it to start the quest.", zone="Silverpine Forest", map=1421, x=59.4, y=71.6, path={{60.2,72.0}}, cave=true},
  {t="T", seg=6, q={95884}, names={"The Offering Stone"}, text="The Offering Stone is in the deepest part of the cave", zone="Silverpine Forest", map=1421, x=58.0, y=69.8, path={{60.2,72.0}}, cave=true},
  {t="A", seg=6, q={95883}, names={"The Tortured Soul"}, text="From the Offering Stone", zone="Silverpine Forest", map=1421, x=58.0, y=69.8},
  {t="C", seg=6, q={95883}, names={"The Tortured Soul"}, text="Kill the undead in the cave until you loot a Tortured Soul", zone="Silverpine Forest", map=1421, x=59.3, y=71.7, path={{60.2,72.0}}, cave=true},
  {t="T", seg=6, q={95883}, names={"The Tortured Soul"}, text="Back at the Offering Stone. Do not take The Offering of Blood from the stone: it summons an elite ghost.", zone="Silverpine Forest", map=1421, x=58.0, y=69.8},
  {t="C", seg=6, q={95981}, names={"Watching the Roads"}, text="Only if you have Watching the Roads (otherwise press Skip): kill 8 Dalaran Wizards and 8 Dalaran Watchers (18-20) on the roads south and east of Ambermill, on your way east toward Hillsbrad. Earth Shock the Wizards' casts.", zone="Silverpine Forest", map=1421, x=61.3, y=76.8},
  {t="A", seg=6, q={494}, names={"Time To Strike"}, text="Take the road east out of Silverpine into the Hillsbrad Foothills. Deathstalker Lesh camps beside the road.", zone="Hillsbrad Foothills", map=1424, x=20.8, y=47.4},
  {t="F", seg=6, arg="Tarren Mill", text="Keep east on the road through the Hillsbrad Fields. Hillsbrad Footmen (25-26) patrol the farms right beside the road, with farmers (22-25) around them: stay in Ghost Wolf, keep moving and do not stop to fight here at 20. Past the fields, take the road north-east up to Tarren Mill and stay well clear of Southshore, the Alliance town further south-east. Talk to Zarise for the flight path.", zone="Hillsbrad Foothills", map=1424, x=60.1, y=18.6},
  {t="C", seg=6, q={1536}, names={"Call of Water"}, text="Use the Empty Red Waterskin at the Spring Well in the middle of town", zone="Hillsbrad Foothills", map=1424, x=62.2, y=20.8},
  {t="T", seg=6, q={493,1065}, names={"Journey to Hillsbrad Foothills","Journey to Tarren Mill"}, text="Apothecary Lydon, a few steps east of Zarise", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="A", seg=6, q={1066,496}, names={"Blood of Innocents","Elixir of Suffering"}, text="Apothecary Lydon. His Elixir of Pain needs level 21: you take it when you are back from Durnholde.", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="T", seg=6, q={494}, names={"Time To Strike"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.5},
  {t="A", seg=6, q={527}, names={"Battle of Hillsbrad"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=6, q={549}, names={"WANTED: Syndicate Personnel"}, text="WANTED poster right next to Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.6, y=20.8},
  {t="A", seg=6, q={498}, names={"The Rescue"}, text="Krusk, a few steps further east", zone="Hillsbrad Foothills", map=1424, x=63.2, y=20.7},
  {t="C", seg=6, q={498,549,1066}, names={"The Rescue","WANTED: Syndicate Personnel","Blood of Innocents"}, text="Durnholde Keep is south-east of Tarren Mill. Kill Syndicate Rogues and Watchmen outside the walls and in the courtyard; Syndicate Shadow Mages drop the Vials of Innocent Blood: Earth Shock their Shadow Bolts. Rogues stealth, so look around before each pull. The prisoners' chains are locked: Jailor Eston (79.6, 41.8) drops the Dull Iron Key and Jailor Marlgen (79.5, 40.6) the Burnished Gold Key. Both are level 24 and stand inside the keep: clear around them, pull each one alone and drop Stoneclaw Totem if an add joins. With both keys, click the ball and chain at Drull (75.3, 41.5) and at Tog'thar (79.8, 39.7) to free them.", zone="Hillsbrad Foothills", map=1424, x=77.5, y=40.5},
  {t="C", seg=6, q={496}, names={"Elixir of Suffering"}, text="Gray Bears drop the tongues and Forest Moss Creepers drop the ichor. Both roam the hills between Durnholde and Tarren Mill.", zone="Hillsbrad Foothills", map=1424, x=64.5, y=33.5},
  {t="T", seg=6, q={498}, names={"The Rescue"}, text="Krusk", zone="Hillsbrad Foothills", map=1424, x=63.2, y=20.7, path={{63.2,31.6},{63.4,28.3},{66.0,25.6},{66.0,23.2}}},
  {t="T", seg=6, q={549}, names={"WANTED: Syndicate Personnel"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.5},
  {t="T", seg=6, q={1066,496}, names={"Blood of Innocents","Elixir of Suffering"}, text="Apothecary Lydon", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="A", seg=6, q={1067,499}, names={"Return to Thunder Bluff","Elixir of Suffering"}, text="Apothecary Lydon. Keep Return to Thunder Bluff for the next segment.", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="T", seg=6, q={499}, names={"Elixir of Suffering"}, text="Umpi, standing next to Lydon", zone="Hillsbrad Foothills", map=1424, x=61.5, y=19.1},
  {t="A", seg=6, q={501}, names={"Elixir of Pain"}, text="Apothecary Lydon: Elixir of Pain (needs level 21). Still 20? Kill Gray Bears on the hills south of town until you ding, then come back for it.", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="C", seg=6, q={501}, names={"Elixir of Pain"}, text="Starving Mountain Lions (23-24) roam the hills west and south-west of Tarren Mill, on the way to the fields", zone="Hillsbrad Foothills", map=1424, x=53.8, y=40.2, path={{59.8,19.3},{57.6,22.3},{59.6,36.7},{57.6,39.7}}},
  {t="C", seg=6, q={527}, names={"Battle of Hillsbrad"}, text="Hillsbrad Fields (around 34, 40): kill Farmhands and Farmers. Farmer Ray is at 33.2, 34.8 and Farmer Getz at 36.7, 39.4. Footmen patrol the farms: pull one at a time and drop Earthbind Totem so runners do not bring friends.", zone="Hillsbrad Foothills", map=1424, x=33.4, y=38.7},
  {t="T", seg=6, q={501}, names={"Elixir of Pain"}, text="Back in Tarren Mill: Apothecary Lydon", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="A", seg=6, q={502}, names={"Elixir of Pain"}, text="Apothecary Lydon", zone="Hillsbrad Foothills", map=1424, x=61.4, y=19.1},
  {t="T", seg=6, q={527}, names={"Battle of Hillsbrad"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=6, q={528}, names={"Battle of Hillsbrad"}, text="High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=6, q={546}, names={"Souvenirs of Death"}, text="Deathguard Samsa. Every Hillsbrad human drops skulls; you finish this on the next Tarren Mill trip.", zone="Hillsbrad Foothills", map=1424, x=62.1, y=19.7},
  {t="A", seg=6, q={567}, names={"Dangerous!"}, text="Dangerous! poster near the inn. You get two of the four names now and the rest on the next Tarren Mill trip.", zone="Hillsbrad Foothills", map=1424, x=62.6, y=19.7},
  {t="T", seg=6, q={502}, names={"Elixir of Pain"}, text="Feed the elixir to Stanley, the dog at Farmer Ray's farm at the north end of the fields. In Classic he then turns into a hostile Enraged Stanley (24); players report that Forever removed this, so he will probably stay friendly. If he does attack, kill him.", zone="Hillsbrad Foothills", map=1424, x=32.7, y=35.3, path={{64.6,19.3},{66.0,22.9},{66.0,25.6},{63.4,28.3},{62.8,32.2},{60.0,31.3},{57.2,26.2},{45.8,26.2},{38.6,34.9},{35.0,34.9},{33.8,36.7}}},
  {t="C", seg=6, q={528,567,567}, obj={0,2,4}, names={"Battle of Hillsbrad","Dangerous!","Dangerous!"}, text="Kill 15 Hillsbrad Peasants in the fields. Citizen Wilkes (25) walks the north edge of the farms around 32.6, 39.8 with a Footman close by: pull them apart. Farmer Kalaba (25) works the field at 35.9, 46.6. Leave Clerk Horrace (town hall) and Miner Hackett for the next trip.", zone="Hillsbrad Foothills", map=1424, x=33.4, y=44.5},
  {t="L", seg=6, lvl=22, text="Only if you are not 22 yet (the step ticks by itself otherwise): keep killing Peasants, Farmers and Farmhands (22-25) in the fields, but do not grind all the way. Stop when your XP bar at level 21 reads about 20,400 / 25,200 (18,850 if you have Watching the Roads) and press Skip: Battle of Hillsbrad, Beren's Peril and Stop the Spread (and Watching the Roads), handed in next, cover the rest. Their skulls count toward Souvenirs of Death.", zone="Hillsbrad Foothills", map=1424, x=34.5, y=44.0},
  {t="T", seg=6, q={528}, names={"Battle of Hillsbrad"}, text="Walk back to Tarren Mill: High Executor Darthalia", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=6, q={529}, names={"Battle of Hillsbrad"}, text="High Executor Darthalia. Keep it: Blacksmith Verringtan (26) is done on the next Tarren Mill trip.", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="A", seg=6, q={98094}, names={"Scout Support"}, text="High Executor Darthalia (new in Forever). Keep it for the next Tarren Mill trip.", zone="Hillsbrad Foothills", map=1424, x=62.3, y=20.4},
  {t="FLY", seg=6, arg="The Sepulcher", text="Zarise. The flight goes through the Undercity."},
  {t="T", seg=6, q={516}, names={"Beren's Peril"}, text="Shadow Priest Allister", zone="Silverpine Forest", map=1421, x=44.0, y=40.9},
  {t="A", seg=6, q={1098}, names={"Deathstalkers in Shadowfang"}, text="High Executor Hadrec at the Sepulcher. It ends inside the keep, at Deathstalker Vincent.", zone="Silverpine Forest", map=1421, x=43.4, y=40.9, dg=4},
  {t="T", seg=6, q={95981}, names={"Watching the Roads"}, text="Shadow Priest Allister (press Skip if you never had Watching the Roads)", zone="Silverpine Forest", map=1421, x=44.1, y=41.0},
  {t="T", seg=6, q={98299}, names={"Stop the Spread"}, text="Dalar Dawnweaver", zone="Silverpine Forest", map=1421, x=44.2, y=39.8},
  {t="A", seg=6, q={1014}, names={"Arugal Must Die"}, text="Dalar Dawnweaver at the Sepulcher. Kill Arugal, the last boss.", zone="Silverpine Forest", map=1421, x=44.2, y=39.8, dg=4},
  {t="N", seg=6, arg="Optional dungeon: Shadowfang Keep, levels 22-30", text="The keep is in the south of Silverpine, on the hill above Pyrewood Village: follow the road south from the Sepulcher. Hand Deathstalkers in Shadowfang in to Deathstalker Vincent inside. Quests you picked up for it: The Book of Ur, Deathstalkers in Shadowfang, Arugal Must Die.", zone="Silverpine Forest", map=1421, x=44.8, y=67.8, dg=4, run=true},
  {t="T", seg=6, q={1014}, names={"Arugal Must Die"}, zone="Silverpine Forest", map=1421, x=44.2, y=39.8, dg=4},
  {t="H", seg=6, arg="Camp Taurajo", text="Back to Kalimdor. Keep the Filled Red Waterskin: Brine is next."},
  {t="T", seg=7, q={1536}, names={"Call of Water"}, text="Run south from Camp Taurajo down the road to Brine's hut (Ghost Wolf). Hand in the Filled Red Waterskin", zone="The Barrens", map=1413, x=43.4, y=77.4},
  {t="A", seg=7, q={1534}, names={"Call of Water"}, text="Brine. Keep the Empty Blue Waterskin: you fill it at the Ruins of Stardust in western Ashenvale later in this segment and bring it back to her next segment", zone="The Barrens", map=1413, x=43.4, y=77.4},
  {t="G", seg=7, text="Run back north to Camp Taurajo's wind rider master", zone="The Barrens", map=1413, x=44.5, y=59.2},
  {t="FLY", seg=7, arg="Thunder Bluff"},
  {t="A", seg=7, q={97538}, names={"Pigments for Paints"}, text="New Forever quest. Tah Winterhoof stands on the central rise, a short walk east of the wind rider master. The pods come from Mirkfallon Lake in Stonetalon. Keep the quest: you hand the pods in on your next Thunder Bluff visit", zone="Thunder Bluff", map=1456, x=54.5, y=47.4},
  {t="T", seg=7, q={1067}, names={"Return to Thunder Bluff"}, text="Apothecary Zamah, in the Pools of Vision under Spirit Rise (the west mesa)", zone="Thunder Bluff", map=1456, x=22.8, y=20.9},
  {t="A", seg=7, q={1086}, names={"The Flying Machine Airport"}, text="Keep the Toxic Fogger. You use it at the goblins' sky port in Windshear Crag at the end of this segment and hand the quest in to Zamah next segment", zone="Thunder Bluff", map=1456, x=22.8, y=20.9},
  {t="TRAIN", seg=7, text="The shaman trainers stand right next to Zamah: learn your level 22 spells", zone="Thunder Bluff", map=1456, x=22.8, y=21.1},
  {t="FLY", seg=7, arg="Crossroads", text="From Tal, back on the central rise"},
  {t="A", seg=7, q={868}, names={"Egg Hunt"}, text="Korran, at the Crossroads. Keep it: the Silithid Eggs come from the Field of Giants south of Camp Taurajo next segment", zone="The Barrens", map=1413, x=51.1, y=29.7},
  {t="G", seg=7, text="Run west along the road to the Stonetalon border, where Seereth Stonebreak stands. Shredding Machines is not done yet: you come back past him on the way to Ashenvale", zone="The Barrens", map=1413, x=35.3, y=27.9},
  {t="A", seg=7, q={1058}, names={"Jin'Zil's Forest Magic"}, text="Witch Doctor Jin'Zil, in the small cave at Malaka'jin just past the border. The parts come from Stonetalon Peak, which you visit soon", zone="Stonetalon Mountains", map=1442, x=74.5, y=97.9},
  {t="A", seg=7, q={1090}, names={"Gerenzo's Orders"}, text="Follow the road north into Windshear Crag. Piznik stands at a mine entrance on the east side of the logging camp", zone="Stonetalon Mountains", map=1442, x=71.9, y=60.0, path={{74.1,59.6}}, cave=true},
  {t="C", seg=7, q={1090}, names={"Gerenzo's Orders"}, text="Piznik mines for about a minute. Stay next to him and kill the Venture Co. goblins that run at him (a Searing Totem beside him helps), then talk to him for the ore", zone="Stonetalon Mountains", map=1442, x=71.9, y=60.0, path={{74.1,59.6}}, cave=true},
  {t="T", seg=7, q={1090}, names={"Gerenzo's Orders"}, zone="Stonetalon Mountains", map=1442, x=71.9, y=60.0},
  {t="A", seg=7, q={1092}, names={"Gerenzo's Orders"}, zone="Stonetalon Mountains", map=1442, x=71.9, y=60.0},
  {t="C", seg=7, q={1068}, obj={1}, names={"Shredding Machines"}, text="XT:4 is a goblin shredder (level 23) working the north end of the logging area, by Cragpool Lake. Gerenzo (level 27) stands on the heights just north of it: leave him alone for now", zone="Stonetalon Mountains", map=1442, x=64.1, y=46.4},
  {t="C", seg=7, q={1068}, obj={2}, names={"Shredding Machines"}, text="XT:9, the second shredder (level 23), works the logging area further south", zone="Stonetalon Mountains", map=1442, x=64.1, y=56.6},
  {t="T", seg=7, q={1095,1092}, names={"Further Instructions","Gerenzo's Orders"}, text="Ziz Fizziks stands under the cliff at the south-west edge of Windshear Crag. He then offers Gerenzo Wrenchwhistle: do not take it yet. You come back for it after Ashenvale, about two levels higher", zone="Stonetalon Mountains", map=1442, x=59.0, y=62.6},
  {t="A", seg=7, q={6301}, names={"Cycle of Rebirth"}, text="Walk west to Sun Rock Retreat. Tammra Windfield, in the middle of the camp", zone="Stonetalon Mountains", map=1442, x=47.5, y=58.4},
  {t="A", seg=7, q={1087}, names={"Cenarius' Legacy"}, text="Braelyn Firehand, on the west side of Sun Rock Retreat. Leave the Charred Vale quests (mobs up to level 27) until you come back after Ashenvale", zone="Stonetalon Mountains", map=1442, x=45.9, y=60.4},
  {t="C", seg=7, q={6301,97538}, names={"Cycle of Rebirth","Pigments for Paints"}, text="Walk north to Mirkfallon Lake. Gaea Seeds lie on the ground around the lake shore. Mirkweed plants grow in the shallow water of the lake; loot 30 Mirkweed Pods from them", zone="Stonetalon Mountains", map=1442, x=48.8, y=40.7},
  {t="C", seg=7, q={1087,1058}, names={"Cenarius' Legacy","Jin'Zil's Forest Magic"}, text="Keep going north to Stonetalon Peak (mobs level 22-25). The Sons and Daughters of Cenarius and the Cenarion Botanists camp south of the Alliance outpost at the Peak (stay away from its guards); Earth Shock the Botanists' heals. Sap Beasts (sap), Twilight Runner cats (whiskers), Antlered and Great Coursers (30 eyes, roughly two per deer) and the small Fey Dragons (one scale) all roam the Peak. You do not need the druids and dryads further west (level 25-27)", zone="Stonetalon Mountains", map=1442, x=36.3, y=13.0, path={{51.4,38.8},{51.4,36.1},{50.0,34.0},{50.0,30.4},{49.0,28.9},{45.6,28.6},{44.0,25.9},{43.2,15.1},{41.6,12.7},{38.8,12.7},{37.6,14.5},{36.4,14.5}}},
  {t="T", seg=7, q={6301}, names={"Cycle of Rebirth"}, text="Walk back south to Sun Rock Retreat. Finish any missing Gaea Seeds or Mirkweed Pods at the lake on the way. Tammra then offers New Life: take it when you come back", zone="Stonetalon Mountains", map=1442, x=47.5, y=58.4},
  {t="T", seg=7, q={1087}, names={"Cenarius' Legacy"}, text="Braelyn then offers Ordanus (level 29). Keeper Ordanus sits at the top of Raynewood Retreat in Ashenvale, among level 25-27 druids. Skip it", zone="Stonetalon Mountains", map=1442, x=45.9, y=60.4},
  {t="A", seg=7, q={6562}, names={"Trouble in the Deeps"}, text="Tsunaman at Sun Rock Retreat. It sends you to Je'neu Sancrea at Zoram'gar Outpost.", zone="Stonetalon Mountains", map=1442, x=47.4, y=64.2, dg=5},
  {t="T", seg=7, q={1058}, names={"Jin'Zil's Forest Magic"}, text="Walk east into Windshear Crag and follow the road south to Jin'Zil's cave at Malaka'jin", zone="Stonetalon Mountains", map=1442, x=74.5, y=97.9},
  {t="A", seg=7, q={6542}, names={"Report to Kadrak"}, text="Darn Talongrip, in the Malaka'jin camp beside Jin'Zil's cave. It sends you to Kadrak, who is on your way north", zone="Stonetalon Mountains", map=1442, x=73.2, y=94.9},
  {t="T", seg=7, q={1068}, names={"Shredding Machines"}, text="Seereth Stonebreak, just across the border in the Barrens", zone="The Barrens", map=1413, x=35.3, y=27.9},
  {t="G", seg=7, text="Run north-east across the Dry Hills to Mor'shan Rampart, the Horde gate at the north end of the Barrens", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="T", seg=7, q={6542}, names={"Report to Kadrak"}, text="Kadrak, on the Mor'shan watch tower", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="A", seg=7, q={6543}, names={"The Warsong Reports"}, text="Kadrak. Right-click the Bundle of Reports for three Warsong Reports. Three Warsong messengers in Ashenvale each take one: talk to each of them, accept his short quest and hand it straight back to get his update", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="A", seg=7, q={6544}, names={"Torek's Assault"}, text="Follow the road north into Ashenvale. Torek and his raiders wait just west of the road, south of Splintertree Post", zone="Ashenvale", map=1440, x=68.3, y=75.3},
  {t="C", seg=7, q={6544}, names={"Torek's Assault"}, text="Tell Torek you are ready; he charges west into Silverwing Outpost. At the end Duriel Moonfire and four elves jump you inside the building. They have little health: drop Stoneclaw Totem to pull some of them off you, Earth Shock Duriel's spells and heal yourself with Healing Wave if you drop low", zone="Ashenvale", map=1440, x=68.3, y=75.3},
  {t="A", seg=7, q={6503}, names={"Ashenvale Outrunners"}, text="Kuray'bin waits by the road a little further north", zone="Ashenvale", map=1440, x=71.1, y=68.1},
  {t="C", seg=7, q={6543}, obj={1}, names={"The Warsong Reports"}, text="The Warsong Scout stands next to Kuray'bin: give him the first report", zone="Ashenvale", map=1440, x=71.0, y=68.4},
  {t="C", seg=7, q={6503}, names={"Ashenvale Outrunners"}, text="Ashenvale Outrunners are stealthed night elf scouts in the woods on both sides of the road around Kuray'bin and Torek. Walk the slopes; they show themselves when they attack. Sharptalon, a level 31 hippogryph, stands on the slope east of the road (around 75, 70) among some Outrunners: hunt the Outrunners away from him", zone="Ashenvale", map=1440, x=73.5, y=72.3},
  {t="T", seg=7, q={6503}, names={"Ashenvale Outrunners"}, zone="Ashenvale", map=1440, x=71.1, y=68.1},
  {t="F", seg=7, arg="Splintertree Post", text="Vhulgra, the wind rider master. Do not bind here: your hearth stays at Camp Taurajo"},
  {t="T", seg=7, q={6544}, names={"Torek's Assault"}, text="Ertog Ragetusk", zone="Ashenvale", map=1440, x=73.0, y=62.5},
  {t="T", seg=7, q={742}, names={"The Ashenvale Hunt"}, text="Senani Thunderheart", zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="A", seg=7, q={6383}, names={"The Ashenvale Hunt"}, zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="T", seg=7, q={6383}, names={"The Ashenvale Hunt"}, text="This opens the Ashenvale Hunt. Sharptalon (level 31, south of the post) is for much later; skip him", zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="L", seg=7, lvl=23, text="Only if you are not level 23 yet (the step ticks by itself otherwise): Mastok's quest and the Befouled Element both need 23. Kill a few more Ashenvale Outrunners in the woods along the road south of the post (stay away from Sharptalon at 75, 70), then come back", zone="Ashenvale", map=1440, x=72.0, y=74.0},
  {t="A", seg=7, q={25}, names={"Stonetalon Standstill"}, text="Mastok Wrilehiss. Also skip: The Lost Pages (Gurda Ragescar, level 30, the pages are random drops) and Warsong Supplies (needs a crate from Booty Bay and an engineering gun). Pixel's Satyr Horns can wait until you come back", zone="Ashenvale", map=1440, x=73.7, y=60.0},
  {t="C", seg=7, q={25}, names={"Stonetalon Standstill"}, text="Mystral Lake is south-west of Splintertree. Kill the Befouled Water Elementals around the lake and walk onto the gazebo on the lake (48.9, 69.6) to scout it. Keep away from Silverwind Refuge, the Alliance camp by the lake", zone="Ashenvale", map=1440, x=49.0, y=70.4},
  {t="A", seg=7, q={1918}, names={"The Befouled Element"}, text="Tideress (level 27) is a named water elemental near the small island in the west of the lake. Her Befouled Water Globe starts this quest. Clear the elementals around her first and fight her at full mana with Stoneclaw Totem down", zone="Ashenvale", map=1440, x=45.9, y=70.6},
  {t="A", seg=7, q={23}, names={"Ursangous's Paw"}, text="Ursangous (level 25, a druid in bear form) patrols the woods west of Mystral Lake. His paw starts this quest. A huge elite treant also patrols here: keep your distance", zone="Ashenvale", map=1440, x=39.8, y=65.2, path={{46.2,67.2},{45.0,64.8},{43.2,64.8},{42.2,66.3}}},
  {t="A", seg=7, q={98251}, names={"Never Coming Back"}, text="New Forever quest. Va'xug Firefure, a lost warlock, sits in a ravine just north of Ursangous", zone="Ashenvale", map=1440, x=40.4, y=61.5},
  {t="C", seg=7, q={98251}, names={"Never Coming Back"}, text="Shadowhorn Stags and Ashenvale Bears roam all around the ravine", zone="Ashenvale", map=1440, x=39.7, y=65.4},
  {t="T", seg=7, q={98251}, names={"Never Coming Back"}, zone="Ashenvale", map=1440, x=40.4, y=61.5},
  {t="A", seg=7, q={98252}, names={"A Void Path"}, zone="Ashenvale", map=1440, x=40.4, y=61.5},
  {t="C", seg=7, q={98252}, names={"A Void Path"}, text="Va'xug's Eye of Kilrogg follows you: lead it out of the ravine to the main road within four minutes. If the channel breaks, go back to her and try again", zone="Ashenvale", map=1440, x=38.6, y=58.3},
  {t="T", seg=7, q={98252}, names={"A Void Path"}, text="Hand it in to the Eye of Kilrogg itself, at the road", zone="Ashenvale", map=1440, x=38.6, y=58.3},
  {t="C", seg=7, q={1534}, names={"Call of Water"}, text="Call of Water. Astranaar (Alliance town, level 40 guards) is north up this road: go the other way. Head south-west from the road to the Ruins of Stardust, a small lake west of Ursangous's woods. Wade to the fountain in the middle of the lake and use the Empty Blue Waterskin there. Keep the Filled Blue Waterskin for Brine", zone="Ashenvale", map=1440, x=33.55, y=67.47},
  {t="G", seg=7, text="Now head north-north-west, keeping Astranaar (around 36, 50) well to your right", zone="Ashenvale", map=1440, x=30.0, y=57.0},
  {t="G", seg=7, text="Turn north-west and cross the forest to Zoram'gar Outpost on the coast. Keep clear of the night elves at around 22, 53 (on your left) and of Maestra's Post (Alliance, around 27, 36, on your right)", zone="Ashenvale", map=1440, x=12.2, y=33.8},
  {t="F", seg=7, arg="Zoram'gar Outpost", text="Andruk, the wind rider master"},
  {t="C", seg=7, q={6543}, obj={2}, names={"The Warsong Reports"}, text="The Warsong Runner is in the outpost: give him the second report", zone="Ashenvale", map=1440, x=12.2, y=34.2},
  {t="A", seg=7, q={6442}, names={"Naga at the Zoram Strand"}, text="Marukai", zone="Ashenvale", map=1440, x=11.7, y=34.9},
  {t="A", seg=7, q={6462}, names={"Troll Charm"}, text="Mitsuwa", zone="Ashenvale", map=1440, x=11.7, y=34.9},
  {t="A", seg=7, q={216}, names={"Between a Rock and a Thistlefur"}, text="Karang Amakkar. Skip Vorsha the Lasher (Muglash) and King of the Foulweald: both are elite", zone="Ashenvale", map=1440, x=11.9, y=34.5},
  {t="C", seg=7, q={6442}, names={"Naga at the Zoram Strand"}, text="Wrathtail naga (level 18-21) line the Zoram Strand. The nearest start just north of the outpost; if they run thin, follow the shore further north. Every kind drops heads. Earth Shock the Sea Witches' and Sorceresses' casts", zone="Ashenvale", map=1440, x=10.5, y=27.5},
  {t="T", seg=7, q={6442}, names={"Naga at the Zoram Strand"}, zone="Ashenvale", map=1440, x=11.7, y=34.9},
  {t="G", seg=7, text="Leave Zoram'gar heading east, bearing a little north. Maestra's Post (Alliance, around 27, 37) sits right on the straight line to Thistlefur and has a level 42 night elf: pass well north of it", zone="Ashenvale", map=1440, x=24.0, y=30.0},
  {t="C", seg=7, q={216}, names={"Between a Rock and a Thistlefur"}, text="Thistlefur Village is the furbolg village further east. Kill the Avengers and Shamans in and around the village. Earth Shock the Shamans when they cast, and pull one at a time", zone="Ashenvale", map=1440, x=36.0, y=36.3},
  {t="C", seg=7, q={6462}, names={"Troll Charm"}, text="Thistlefur Hold is the cave at the east end of the village. Troll Chests sit along its tunnels; each holds a Troll Charm", zone="Ashenvale", map=1440, x=40.7, y=33.6},
  {t="A", seg=7, q={6482}, names={"Freedom to Ruul"}, text="Ruul Snowhoof is a captive tauren deep inside Thistlefur Hold", zone="Ashenvale", map=1440, x=41.5, y=34.5},
  {t="C", seg=7, q={6482}, names={"Freedom to Ruul"}, text="Escort Ruul out of the cave. Furbolgs ambush you on the way: drop Stoneclaw Totem next to him so they turn on it, and keep them off him. Afterwards you only need to talk to his sister in Splintertree. Keep 216 and 6462: you hand them in on a later flight back to Zoram'gar", zone="Ashenvale", map=1440, x=41.5, y=34.5},
  {t="G", seg=7, text="Run south-east across the middle of Ashenvale. Astranaar (around 36, 50) stays to your south-west, and the worgen (level 29-32, around 50, 39) stay north of your path. The Laughing Sisters (dryads, 24-25) roam the woods below Raynewood Retreat: kill them until one drops an Etched Phial (for The Sacred Flame). Do not go up into Raynewood Retreat (around 62, 51): groups of druids guard it. Shadumbra (level 28 panther) patrols these same woods; her head starts Shadumbra's Head. Take her on now only if you are already level 24 (at 23 she is red and your shocks miss a lot): full health and mana, Stoneclaw Totem down, heal early. Otherwise keep clear of her: you get a second chance after Night Run", zone="Ashenvale", map=1440, x=59.8, y=55.0},
  {t="G", seg=7, text="Phial in hand, head south-west first, around the guarded moonwell (59, 59-60): its level 40 night elf sentinels stand right on the straight line south. Leave the Laughing Sisters next to it alone", zone="Ashenvale", map=1440, x=56.5, y=61.0},
  {t="C", seg=7, q={1195}, names={"The Sacred Flame"}, text="Now walk south-south-east, cross the main road and use the Etched Phial at the moonwell on the west bank of the Falfarren River. Keep the Filled Etched Phial for Thunder Bluff next segment", zone="Ashenvale", map=1440, x=60.2, y=72.9},
  {t="G", seg=7, text="Walk east to the Horde road, passing north of Silverwing Outpost, then follow it north to Splintertree Post", zone="Ashenvale", map=1440, x=69.7, y=71.7},
  {t="T", seg=7, q={6482}, names={"Freedom to Ruul"}, text="Yama Snowhoof", zone="Ashenvale", map=1440, x=74.1, y=60.9},
  {t="T", seg=7, q={23}, names={"Ursangous's Paw"}, text="Senani Thunderheart. If you already have Shadumbra's Head, hand it in too", zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="T", seg=7, q={25,1918}, names={"Stonetalon Standstill","The Befouled Element"}, text="Mastok Wrilehiss", zone="Ashenvale", map=1440, x=73.7, y=60.0},
  {t="A", seg=7, q={824}, names={"Je'neu of the Earthen Ring"}, text="The globe goes to Je'neu at Zoram'gar; you fly there once Ashenvale is done", zone="Ashenvale", map=1440, x=73.7, y=60.0},
  {t="A", seg=7, q={6441}, names={"Satyr Horns"}, text="Pixel", zone="Ashenvale", map=1440, x=73.1, y=61.5},
  {t="C", seg=7, q={6543}, obj={3}, names={"The Warsong Reports"}, text="Follow the road east out of Splintertree toward Azshara. The Warsong Outrider waits by the road: give him the last report", zone="Ashenvale", map=1440, x=81.8, y=53.5},
  {t="C", seg=7, q={6441}, names={"Satyr Horns"}, text="Come back west to Night Run, the satyr valley north-west of Splintertree. Every Felmusk satyr (level 25-27) can drop horns. The Felsworn cast: Earth Shock them. Pull one at a time; Rogues and Shadowstalkers come out of stealth", zone="Ashenvale", map=1440, x=67.5, y=54.5},
  {t="A", seg=7, q={24}, names={"Shadumbra's Head"}, text="Shadumbra, second chance (the step ticks by itself if her head is already in your log or handed in). She patrols the woods about 600 yards west of Night Run, just south of Raynewood Retreat. Fight her only at level 24 or higher: full health and mana, Stoneclaw Totem down, Flame Shock, heal early. Still 23? Press Skip here and on her turn-in. Do not pull her toward the sentinels' moonwell (59, 60)", zone="Ashenvale", map=1440, x=57.5, y=56.0},
  {t="T", seg=7, q={6441}, names={"Satyr Horns"}, text="Back east to Pixel in Splintertree", zone="Ashenvale", map=1440, x=73.1, y=61.5},
  {t="T", seg=7, q={24}, names={"Shadumbra's Head"}, text="Senani Thunderheart (press Skip if you left Shadumbra)", zone="Ashenvale", map=1440, x=73.8, y=61.5},
  {t="G", seg=7, text="Follow the road south out of Ashenvale to Mor'shan Rampart", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="T", seg=7, q={6543}, names={"The Warsong Reports"}, text="Kadrak", zone="The Barrens", map=1413, x=48.1, y=5.4},
  {t="G", seg=7, text="Run back north to Splintertree Post's wind rider master", zone="Ashenvale", map=1440, x=73.2, y=61.6},
  {t="FLY", seg=7, arg="Zoram'gar Outpost"},
  {t="T", seg=7, q={824,216,6462}, names={"Je'neu of the Earthen Ring","Between a Rock and a Thistlefur","Troll Charm"}, text="Je'neu Sancrea, Karang Amakkar and Mitsuwa, all in the outpost", zone="Ashenvale", map=1440, x=11.6, y=34.3},
  {t="T", seg=7, q={6562}, names={"Trouble in the Deeps"}, zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5, req=6562},
  {t="A", seg=7, q={6563}, names={"The Essence of Aku'Mai"}, text="20 Sapphires of Aku'Mai: they grow on the walls of the tunnels before the dungeon portal.", zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5, req=6562},
  {t="A", seg=7, q={6921}, names={"Amongst the Ruins"}, text="Je'neu Sancrea. The Fathom Core is under water in the first big pool inside the dungeon.", zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5},
  {t="N", seg=7, arg="Optional dungeon: Blackfathom Deeps, levels 24-32", text="The entrance is on the coast north of Zoram'gar Outpost: go down through the ruins and the tunnels to the portal. On the way, the naga and satyrs can drop a Damp Note; hand it to Je'neu to get Allegiance to the Old Gods (kill Lorgus Jett inside). Inside: Argent Guard Thaelrid gives Blackfathom Villainy (the head of Twilight Lord Kelris). Quests you picked up for it: The Essence of Aku'Mai, Amongst the Ruins.", zone="Ashenvale", map=1440, x=14.5, y=14.2, dg=5, run=true},
  {t="T", seg=7, q={6563}, names={"The Essence of Aku'Mai"}, zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5},
  {t="T", seg=7, q={6921}, names={"Amongst the Ruins"}, zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5},
  {t="T", seg=7, q={6565}, names={"Allegiance to the Old Gods"}, text="Allegiance to the Old Gods, if you got it from the Damp Note.", zone="Ashenvale", map=1440, x=11.6, y=34.3, dg=5},
  {t="FLY", seg=7, arg="Sun Rock Retreat", text="A long flight with stops on the way"},
  {t="A", seg=7, q={6381}, names={"New Life"}, text="Tammra Windfield, in the middle of Sun Rock Retreat", zone="Stonetalon Mountains", map=1442, x=47.5, y=58.4},
  {t="A", seg=7, q={6282,86576}, names={"Harpies Threaten","Bloodfury Trinkets"}, text="Maggran Earthbinder gives both. 86576 Bloodfury Trinkets is new in Forever; its sunstones go to Mor'rogal, who stands next to Tsunaman", zone="Stonetalon Mountains", map=1442, x=47.2, y=61.2},
  {t="A", seg=7, q={6393}, names={"Elemental War"}, text="Tsunaman, on the hill at the south end of Sun Rock Retreat", zone="Stonetalon Mountains", map=1442, x=47.4, y=64.2},
  {t="C", seg=7, q={6381,6282,86576,6393}, names={"New Life","Harpies Threaten","Bloodfury Trinkets","Elemental War"}, text="The Charred Vale is the burnt valley west and south-west of Sun Rock. Plant the seeds in the Gaea Dirt Mounds on the valley floor. Kill all four kinds of Bloodfury harpy: Harpies and Ambushers (level 23-24), Slayers and Roguefeathers (25-26); Glittering Sunstones drop from them. Storm Witches (26-27) hit hard: pull them one at a time and Earth Shock their casts. Incendrites drop from the fire elementals: Rogue Flame Spirits (23-24) on the way in, Burning Ravagers (24-25) and Burning Destroyers (26-27) deeper in the vale; Frost Shock the Destroyers and fight them one at a time. Leave Bloodfury Ripper (elite) alone", zone="Stonetalon Mountains", map=1442, x=33.1, y=68.0},
  {t="T", seg=7, q={6393}, names={"Elemental War"}, text="Back to Sun Rock: Tsunaman, on the south hill", zone="Stonetalon Mountains", map=1442, x=47.4, y=64.2},
  {t="T", seg=7, q={86576}, names={"Bloodfury Trinkets"}, text="Mor'rogal, next to Tsunaman", zone="Stonetalon Mountains", map=1442, x=47.2, y=64.0},
  {t="T", seg=7, q={6282}, names={"Harpies Threaten"}, text="Maggran then offers Bloodfury Bloodline (elite). Skip it", zone="Stonetalon Mountains", map=1442, x=47.2, y=61.2},
  {t="A", seg=7, q={5881}, names={"Calling in the Reserves"}, text="Maggran's letter goes to Grish Longrunner at the Great Lift next segment. Keep it", zone="Stonetalon Mountains", map=1442, x=47.2, y=61.2},
  {t="T", seg=7, q={6381}, names={"New Life"}, text="Tammra Windfield", zone="Stonetalon Mountains", map=1442, x=47.5, y=58.4},
  {t="L", seg=7, lvl=25, text="Only if you are not level 25 yet (the step ticks by itself otherwise): walk back west into the Charred Vale and kill Bloodfury harpies and fire elementals (23-27) until 25. Gerenzo is level 27, so the extra level helps", zone="Stonetalon Mountains", map=1442, x=33.0, y=67.0},
  {t="A", seg=7, q={1096}, names={"Gerenzo Wrenchwhistle"}, text="Walk east to Ziz Fizziks, under the cliff at the south-west edge of Windshear Crag", zone="Stonetalon Mountains", map=1442, x=59.0, y=62.6},
  {t="C", seg=7, q={1086}, names={"The Flying Machine Airport"}, text="Walk north through Windshear Crag. The sky port is the goblins' landing pad with a parked flying machine, just east of where XT:4 worked: use the Toxic Fogger there, then leave", zone="Stonetalon Mountains", map=1442, x=66.5, y=45.5},
  {t="C", seg=7, q={1096}, names={"Gerenzo Wrenchwhistle"}, text="Gerenzo Wrenchwhistle (level 27) watches the site from high above Cragpool Lake, a little north-west of the pad, next to the big water wheel; follow the path up. Clear the goblins around him first, then pull him alone at full health and mana: Stoneclaw Totem and Searing Totem down, Flame Shock, Earth Shock if he casts, Healing Wave below half health. Loot his Mechanical Arm", zone="Stonetalon Mountains", map=1442, x=64.5, y=40.2},
  {t="T", seg=7, q={1096}, names={"Gerenzo Wrenchwhistle"}, text="Back south to Ziz Fizziks", zone="Stonetalon Mountains", map=1442, x=59.0, y=62.6},
  {t="H", seg=7, arg="Camp Taurajo", text="Next segment starts here"},
  {t="A", seg=8, q={893}, names={"Weapons of Choice"}, text="Tatternack Steelforge, at the forge in Camp Taurajo", zone="The Barrens", map=1413, x=45.1, y=57.7},
  {t="A", seg=8, q={879}, names={"Betrayal from Within"}, text="Mangletooth, the quilboar in the cage", zone="The Barrens", map=1413, x=44.5, y=59.3},
  {t="A", seg=8, q={1130}, names={"Melor Sends Word"}, text="Jorn Skyseer, in Camp Taurajo. Keep it in your log for Melor Stonehoof in Thunder Bluff (a later segment; his next quest is level 30)", zone="The Barrens", map=1413, x=44.9, y=59.1},
  {t="A", seg=8, q={884}, names={"Owatanka"}, text="Optional: Owatanka, a named thunderhawk, flies around Camp Taurajo. Its Tailspike starts this quest. Skip if you don't see it", zone="The Barrens", map=1413, x=47.0, y=61.0},
  {t="A", seg=8, q={883}, names={"Lakota'mani"}, text="Optional: Lakota'mani, a named grey kodo, wanders just north of Camp Taurajo. Its Hoof starts this quest. Skip if you don't see it", zone="The Barrens", map=1413, x=47.2, y=51.6, path={{48.6,60.6},{48.8,57.6},{48.8,54.9}}},
  {t="C", seg=8, q={868}, names={"Egg Hunt"}, text="Field of Giants south of Camp Taurajo: loot Silithid Eggs from the mounds and kill the silithid around them (they drop eggs too). Ghost Wolf between the mounds", zone="The Barrens", map=1413, x=45.2, y=70.8, path={{48.8,54.6},{48.6,66.3},{47.4,72.0},{45.2,72.0}}},
  {t="A", seg=8, q={98093}, names={"Field to Clear"}, text="Sulhasa is stuck up a tree beside the road south of the silithid field, with lizards and hyenas all around her", zone="The Barrens", map=1413, x=47.9, y=77.6, path={{44.8,78.0}}},
  {t="A", seg=8, q={885}, names={"Washte Pawne"}, text="Optional: Washte Pawne, a named wind serpent, flies over the fields here. Its Feather starts this quest. Skip if you don't see it", zone="The Barrens", map=1413, x=44.8, y=78.9},
  {t="A", seg=8, q={843}, names={"Gann's Reclamation"}, text="Gann Stonespire, at his camp north of Bael Modan", zone="The Barrens", map=1413, x=45.9, y=77.0},
  {t="C", seg=8, q={843}, names={"Gann's Reclamation"}, text="Bael Modan dig site to the south: kill Bael'dun Excavators and Foremen. Prospector Khazgorm in the pit drops the journal. Kill Stormhide and Hecklefang Stalkers for Field to Clear on every trip", zone="The Barrens", map=1413, x=47.6, y=85.2},
  {t="T", seg=8, q={843}, names={"Gann's Reclamation"}, zone="The Barrens", map=1413, x=45.9, y=77.0},
