  {t="C", seg=8, q={893,879}, names={"Weapons of Choice","Betrayal from Within"}, text="Blackthorn Ridge, south-west of Gann: Razormane Pathfinders/Stalkers drop the Backstabber, Seers the Wand, Warfrenzy the Shield. Kuz is at 45,80, Nak at 44,83, Lok Orcbane at 40,80. Earth Shock the Seers' casts", zone="The Barrens", map=1413, x=42.8, y=81.3},
  {t="C", seg=8, q={849}, names={"Revenge of Gann"}, text="From Nak's camp ride east into the dig site and click the Bael Modan Flying Machine (47.0,85.6) to blow it up", zone="The Barrens", map=1413, x=47.0, y=85.6},
