  {t="C", seg=8, q={4966}, names={"Protect Kanati Greycloud"}, text="Only if you did Assassination Plot (4881). Centaurs attack Kanati: Stoneclaw Totem, kill them one at a time. Redo it if he dies", zone="Thousand Needles", map=1441, x=21.2, y=32.1},
