  {t="C", seg=8, q={5064}, names={"Grimtotem Spying"}, text="Darkcloud Pinnacle: the three Secret Notes are in Document Chests in the Grimtotem camps around its base (about 32,33 / 34,40 / 39,41.5)", zone="Thousand Needles", map=1441, x=36.6, y=40.8},
  {t="C", seg=8, q={5147}, names={"Wanted - Arnak Grimtotem"}, text="Arnak Grimtotem (level 29) is at the top of Darkcloud Pinnacle: pull him at full health and mana with Stoneclaw Totem down", zone="Thousand Needles", map=1441, x=38.1, y=26.9},
