  {t="T", seg=8, q={4904}, names={"Free at Last"}, text="Ride back south-east to Freewind Post. Thalia Amberhide", zone="Thousand Needles", map=1441, x=46.0, y=51.6, path={{39.6,26.2},{44.4,33.1},{42.4,37.6},{45.8,43.3}}},
