  {t="T", seg=8, q={220}, names={"Call of Water"}, text="Islen Waterseer, in the fishing hut on the shore a short run south of Ratchet. She gives you a Water Sapta: keep it in your bags and do NOT drink it yet. You drink it at the Brazier of Everfount next segment, and only Islen can make you a new one", zone="The Barrens", map=1413, x=65.8, y=43.8},
  {t="A", seg=8, q={63}, names={"Call of Water"}, text="She also hands you the Remaining Drops of Purest Water. Keep the quest, the drops and the sapta for the Brazier of Everfount in Silverpine Forest (next segment)", zone="The Barrens", map=1413, x=65.8, y=43.8},
  {t="A", seg=8, q={873}, names={"Isha Awak"}, text="Mahren Skyseer, in the same hut", zone="The Barrens", map=1413, x=65.8, y=43.9},
  {t="C", seg=8, q={873}, names={"Isha Awak"}, text="Isha Awak is a big threshadon (level 27) swimming off this coast to the south, around 63,54. Pull it into the shallows so you fight standing, not swimming, and Healing Wave yourself when you drop low", zone="The Barrens", map=1413, x=63.5, y=53.9},
  {t="T", seg=8, q={873}, names={"Isha Awak"}, zone="The Barrens", map=1413, x=65.8, y=43.9},
