  {t="TRAIN", seg=9, text="Orgrimmar, Valley of Wisdom: learn your level 28 spells. Not 28 yet? Skip it; you train in Thunder Bluff next segment", zone="Orgrimmar", map=1454, x=38.8, y=36.4},
