  {t="A", seg=17, q={3042}, names={"Troll Temper"}, text="Trenton Lighthammer in Gadgetzan. 20 Vials of Troll Temper from the trolls inside.", zone="Tanaris", map=1446, x=51.4, y=28.8, dg=13},
  {t="A", seg=17, q={2768}, names={"Divino-matic Rod"}, text="Chief Engineer Bilgewhizzle in Gadgetzan. The rod drops from Sergeant Bly after the stairs fight.", zone="Tanaris", map=1446, x=52.5, y=28.5, dg=13},
  {t="T", seg=17, q={2606}, names={"In Good Taste"}, text="Sprinkle, a few steps away", zone="Tanaris", map=1446, x=51.1, y=26.9},
  {t="A", seg=17, q={2641}, names={"Sprinkle's Secret Ingredient"}, text="Sprinkle. The Violet Tragan grows under water in a small Hinterlands lake (segment 19).", zone="Tanaris", map=1446, x=51.1, y=26.9},
  {t="N", seg=17, arg="Optional dungeon: Zul'Farrak, levels 44-54", text="The entrance is in the north-west corner of Tanaris, a short ride from Gadgetzan. Quests you picked up for it: Scarab Shells, Tiara of the Deep, Gahz'rilla, The Prophecy of Mosh'aru, Troll Temper, Divino-matic Rod. The route does not come back to these hand-ins, go when it suits you: The Prophecy of Mosh'aru (Tanaris); Gahz'rilla (Thousand Needles); Tiara of the Deep (Dustwallow Marsh).", zone="Tanaris", map=1446, x=38.7, y=20.1, dg=13, run=true},
  {t="T", seg=17, q={2865}, names={"Scarab Shells"}, zone="Tanaris", map=1446, x=51.6, y=26.8, dg=13},
