  {t="FLY", seg=17, arg="Ratchet", text="Bulkrek Ragefist, the Gadgetzan wind rider master"},
  {t="N", seg=17, arg="Take the boat from the Ratchet dock to Booty Bay", text="Your hearthstone stays set to Gadgetzan. Keep these for later: 648, 2767 and 2874 (Booty Bay), 712 (Badlands), 584 and 598 (Grom'gol), 698 (Swamp of Sorrows), 864 (Undercity), 650 and 2641 (Hinterlands), 32 (Orgrimmar)."},
  {t="T", seg=18, q={648,2767}, names={"Rescue OOX-17/TN!","Rescue OOX-22/FE!"}, text="Off the boat, walk up to Oglethorpe Obnoticus. His next quest, An OOX of Your Own, only opens once the third robot (Hinterlands, next segment) is home", zone="Stranglethorn Vale", map=1434, x=28.4, y=76.3},
  {t="A", seg=18, q={595}, names={"The Bloodsail Buccaneers"}, text="First Mate Crazz, next to Oglethorpe", zone="Stranglethorn Vale", map=1434, x=28.1, y=76.2},
