  {t="T", seg=18, q={2874}, names={"Deliver to MacKinley"}, text="\"Sea Wolf\" MacKinley", zone="Stranglethorn Vale", map=1434, x=27.8, y=77.1},
  {t="A", seg=18, q={606}, names={"Scaring Shaky"}, text="\"Sea Wolf\" MacKinley", zone="Stranglethorn Vale", map=1434, x=27.8, y=77.1},
  {t="A", seg=18, q={600,621}, names={"Venture Company Mining","Zanzil's Secret"}, text="Crank Fizzlebub, in the inn", zone="Stranglethorn Vale", map=1434, x=27.1, y=77.2},
  {t="A", seg=18, q={209}, names={"Skullsplitter Tusks"}, text="Kebok, in the inn", zone="Stranglethorn Vale", map=1434, x=27.0, y=77.1},
  {t="S", seg=18, arg="Booty Bay", text="Innkeeper Skindle. Your hearthstone still points at Gadgetzan; you hearth back here from Nesingwary's camp", zone="Stranglethorn Vale", map=1434, x=27.0, y=77.3},
  {t="A", seg=18, q={617}, names={"Akiris by the Bundle"}, text="Privateer Bloads", zone="Stranglethorn Vale", map=1434, x=26.8, y=76.4},
  {t="N", seg=18, arg="Keep 15 Silk Cloth in your bags from now on: an outhouse quest at the end of this segment needs it", text="The pirates and trolls here drop plenty. Short? Booty Bay has an Auction House"},
  {t="T", seg=18, q={595}, names={"The Bloodsail Buccaneers"}, text="Take the road north out of Booty Bay to the pirate cove. The Bloodsail Correspondence lies in the camp, guarded by Bloodsail Raiders and Mages (39-41)", zone="Stranglethorn Vale", map=1434, x=27.3, y=69.5},
  {t="A", seg=18, q={597}, names={"The Bloodsail Buccaneers"}, text="From the same papers", zone="Stranglethorn Vale", map=1434, x=27.3, y=69.5},
  {t="C", seg=18, q={617}, names={"Akiris by the Bundle"}, text="Naga Explorers (43-44) walk the beach north of the cove; about 1 in 3 drops Akiris Reed. Earth Shock their casts", zone="Stranglethorn Vale", map=1434, x=26.2, y=62.0},
  {t="A", seg=18, q={349}, names={"Stranglethorn Fever"}, text="Witch Doctor Unbagwa, inland to the east among the gorillas of Mistvale Valley", zone="Stranglethorn Vale", map=1434, x=35.3, y=60.4},
  {t="C", seg=18, q={606,349}, names={"Scaring Shaky","Stranglethorn Fever"}, text="Elder Mistvale Gorillas around Unbagwa: you need 5 Mistvale Giblets (about 1 in 3 drops one) and 10 Gorilla Fangs (about half)", zone="Stranglethorn Vale", map=1434, x=32.9, y=64.6},
  {t="T", seg=18, q={349}, names={"Stranglethorn Fever"}, text="Hand Unbagwa the fangs. He calls waves of gorillas and then Mokk the Savage (44): stay next to him, put Stoneclaw Totem and Magma Totem down for each wave and Healing Wave between them", zone="Stranglethorn Vale", map=1434, x=35.3, y=60.4},
  {t="C", seg=18, q={348}, names={"Stranglethorn Fever"}, text="Loot the Heart of Mokk", zone="Stranglethorn Vale", map=1434, x=35.3, y=60.4},
  {t="T", seg=18, q={606}, names={"Scaring Shaky"}, text="Back to Booty Bay: \"Shaky\" Phillipe on the dock", zone="Stranglethorn Vale", map=1434, x=26.9, y=73.6},
  {t="A", seg=18, q={607}, names={"Return to MacKinley"}, zone="Stranglethorn Vale", map=1434, x=26.9, y=73.6},
