  {t="C", seg=23, q={5235}, names={"Target: Gahrron's Withering"}, text="Gahrron's Withering, east: kill Cauldron Lord Soulwrath beside the cauldron", zone="Western Plaguelands", map=1422, x=62.5, y=58.5, path={{58.8,57.6}}},
